// A library like Boost.TypeIndex provides tools for accurate type reporting.
// The following simulates its usage.

template<typename T>
void print_type_info() {
    // In a real library, this would use demangling to get a clean name
    std::cout << __PRETTY_FUNCTION__ << '\n';
}

template<typename T>
void f(T&& param) { // Universal reference
    std::cout << "T's deduced type: ";
    print_type_info<T>();

    std::cout << "param's type: ";
    print_type_info<decltype(param)>();
}

int x = 0;
f(x); // T is int&, param is int&
f(42); // T is int, param is int&&
